#!/bin/bash
# server=build.palaso.org
# project=Bloom
# build=Bloom-Default-Continuous
# root_dir=..
# Originally auto-generated by https://github.com/sillsdev/BuildUpdate, but that generator is
# obsolete and we no longer use it: this file is now maintained directly. Edit it by hand.
# See "ReadMe - Updating getDependencies scripts.txt" for how to add or change a dependency.
# The "*** Results ***" comment block below is a leftover of the generated era; it is just
# documentation of where these artifacts come from, so keep it roughly in step with the
# copy_auto lines.

# this has nothing to do with dependencies, but putting it here
# so that it gets run. This allows blame to see through
# commits that are only there to format code.
git config blame.ignoreRevsFile .git-blame-ignore-revs

cd "$(dirname "$0")"

# *** Functions ***
force=0
clean=0

while getopts fc opt; do
case $opt in
f) force=1 ;;
c) clean=1 ;;
esac
done

shift $((OPTIND - 1))

# The dependencies we failed to get. We collect them all rather than dying on the first
# one, because a developer whose network (or build server) is unhappy wants the whole list.
failures=()

# Every file we tried to fetch this run, the ones we borrowed from another worktree rather
# than downloading, and whether any zip failed to unpack. Together these let report_failures
# say what actually matters to the developer: is anything missing, or do we have a complete
# set that we simply could not check for updates?
destinations=()
borrowed_dest=()
borrowed_from=()
verified=()
# A file borrowed from a sibling this run, vouched for by the donor's record but not yet by
# the server (see seed_from_sibling_worktree).
seeded_dest=""
seeded_source=""
extraction_failed=0
deleted_a_corrupt_zip=0

# Note that the file now at $1 was checked against the server during this run -- either it
# came down fresh or the server said our copy was current. Borrowing from another worktree
# records nothing here, which is the distinction report_failures reports on.
note_verified() {
verified+=("$1")
}

# True if $1 was checked against the server during this run.
was_verified() {
local one
for one in "${verified[@]}"
do
if [ "$one" == "$1" ]
then
return 0
fi
done
return 1
}

# Where we record which URL each dependency was last fetched from. Without this, the only thing
# vouching for a file on disk is its timestamp, and a timestamp cannot tell us WHICH build a
# file came from -- so an error page left behind by an older version of this script, or an
# artifact downloaded while the worktree was on a branch that gets it from a different build
# (Version6.4 points several of these at bloom-6.4+.tcbuildtag rather than latest.lastSuccessful),
# would answer "not modified" for an artifact it never came from and be locked in forever.
# One consequence worth knowing: the first run after this file gained provenance has no record
# for anything, so it re-downloads the lot once. That is the honest outcome -- we genuinely do
# not know where the existing files came from.
sources_file=../Downloads/dependency-sources.txt

# The partial download in flight, if any, so that Ctrl-C does not leave a
# "something.dll.getDependencies-download" behind in DistFiles or lib -- those directories get
# packaged, and a stray temp file there would ship.
current_temp=""
trap 'rm -f "$current_temp"; exit 130' INT TERM

# How many dependencies in a row the server has not answered at all, and when to stop asking.
# Without this, an unreachable build server costs 16 dependencies x connect timeout x retries --
# minutes of silence before the summary appears, when the useful thing is to say "the server is
# not answering" while the developer is still watching.
no_response_run=0
give_up_after=3
server_unreachable=0
skipped_after_giving_up=0

# The URL a dependency was last fetched from, per a worktree's record. $1 is the record file,
# $2 the destination as written in the copy_auto lines. Prints nothing if there is no record.
recorded_source() {
if [ ! -f "$1" ]
then
return 0
fi
awk -F'\t' -v want="$2" '$1 == want { url = $2 } END { if (url != "") print url }' "$1"
}

# Remember that the file now at $1 came from $2, replacing any previous record for $1.
record_source() {
local temp="$sources_file.new"
if [ -f "$sources_file" ]
then
awk -F'\t' -v want="$1" '$1 != want' "$sources_file" > "$temp"
else
: > "$temp"
fi
printf '%s\t%s\n' "$1" "$2" >> "$temp"
mv -f "$temp" "$sources_file"
}

# Report one problem now (so it appears next to the download it belongs to) and remember it
# for the summary at the end.
note_failure() {
echo "*** ERROR: $1" >&2
failures+=("$1")
}

# Fail the script if any dependency could not be obtained, with a summary loud enough to
# spot in the middle of init.sh's interleaved parallel output.
report_failures() {
if [ ${#failures[@]} -eq 0 ]
then
return 0
fi
local missing=()
local destination
for destination in "${destinations[@]}"
do
# An error page sitting where a dependency should be does not count as "present" -- saying
# so is how this summary would end up telling the developer their broken checkout is fine.
if [ ! -s "$destination" ] || looks_like_html "$destination"
then
missing+=("$destination")
fi
done
echo "" >&2
echo "**********************************************************************" >&2
echo "*** getDependencies-windows.sh FAILED: ${#failures[@]} problem(s):" >&2
for failure in "${failures[@]}"
do
echo "***   $failure" >&2
done
echo "***" >&2
if [ ${#missing[@]} -ne 0 ]
then
echo "*** ${#missing[@]} of ${#destinations[@]} dependencies are MISSING altogether:" >&2
for destination in "${missing[@]}"
do
echo "***   $destination" >&2
done
echo "*** This checkout CANNOT build until those downloads succeed." >&2
else
echo "*** All ${#destinations[@]} dependencies are present on disk even so, so this checkout" >&2
echo "*** can probably still build. What failed was checking them against the server, so" >&2
echo "*** we do not know they are up to date -- which is why this is still a failure." >&2
# Only the borrowed files whose own check never happened are unverified. One that the
# server confirmed (304) or replaced during this run has been checked like any other, and
# saying otherwise would send the developer looking for a problem that is not there.
local unverified=()
local index=0
while [ "$index" -lt "${#borrowed_dest[@]}" ]
do
if ! was_verified "${borrowed_dest[$index]}"
then
unverified+=("${borrowed_dest[$index]} (from ${borrowed_from[$index]})")
fi
index=$((index + 1))
done
if [ ${#unverified[@]} -ne 0 ]
then
echo "*** Note that ${#unverified[@]} of them we copied from another worktree during this run and" >&2
echo "*** never managed to check against the server at all:" >&2
for destination in "${unverified[@]}"
do
echo "***   $destination" >&2
done
fi
fi
if [ "$extraction_failed" == "1" ]
then
echo "*** A zip failed to unpack (see above), so what was extracted from it is probably" >&2
echo "*** incomplete." >&2
fi
echo "***" >&2
echo "*** No file was replaced by whatever the server sent instead: anything we could not" >&2
echo "*** verify was left exactly as it was. (Dependencies that did download cleanly during" >&2
echo "*** this run were of course updated.)" >&2
if [ "$deleted_a_corrupt_zip" == "1" ]
then
echo "*** (Except a zip that turned out to be damaged, which was deleted on purpose so" >&2
echo "*** that the next run downloads it again rather than trusting it.)" >&2
fi
echo "*** Check https://build.palaso.org and your network, then run this script" >&2
echo "*** (or ./init.sh) again." >&2
echo "**********************************************************************" >&2
exit 1
}

# True if the file starts out looking like an HTML document. TeamCity, and any proxy or
# captive portal between us and it, reports problems with an HTML page -- sometimes even
# with a 200 status. None of our dependencies are HTML, so such a page is always an error
# report we must not mistake for the artifact we asked for.
# (Done with bash's own "read -N" rather than head|grep because in Git Bash on Windows grep
# aborts when fed binary data through a pipe, which would make every check silently pass.)
looks_like_html() {
local start
IFS= read -r -N 1024 start < "$1" || true
start="${start,,}"
case "$start" in
*"<!doctype html"*|*"<html"*|*"<head>"*) return 0 ;;
esac
return 1
}

# The other working trees of this repo (the main checkout plus any git worktrees), as absolute
# paths. Empty until find_sibling_worktrees has run, and empty forever if git can't tell us.
sibling_worktrees=()
sibling_worktrees_known=0

# Fill in sibling_worktrees, once.
find_sibling_worktrees() {
if [ "$sibling_worktrees_known" == "1" ]
then
return 0
fi
sibling_worktrees_known=1
local here
here=$(git -C .. rev-parse --show-toplevel 2>/dev/null) || return 0
local line
local tree
while IFS= read -r line
do
case "$line" in
"worktree "*)
tree="${line#worktree }"
if [ "$tree" != "$here" ] && [ -d "$tree" ]
then
sibling_worktrees+=("$tree")
fi
;;
esac
done < <(git -C .. worktree list --porcelain 2>/dev/null)
}

# These dependencies change rarely, and a developer typically has several worktrees of this
# repo, each of which has already downloaded them. So when we haven't got a file at all
# (a brand new worktree, mostly), copy the newest copy a sibling worktree has, timestamp and
# all, before asking the network for it. That is not a substitute for checking with the
# server: the borrowed timestamp is what the conditional GET in copy_curl then sends, so the
# server still gets to say "that is current" (304, and we saved the whole download) or hand
# us something newer.
# $1 is the URL we are about to download, $2 the file we want.
seed_from_sibling_worktree() {
# with -f the caller wants a fresh download regardless, so there is nothing to save
if [ -s "$2" ] || [ "$force" == "1" ]
then
return 0
fi
find_sibling_worktrees
# our destinations are all "../something"; that "something" is the path within a worktree
local relative="${2#../}"
local candidate
local newest=""
local tree
for tree in "${sibling_worktrees[@]}"
do
candidate="$tree/$relative"
if [ ! -f "$candidate" ] || [ ! -s "$candidate" ]
then
continue
fi
# Only borrow a file the other worktree recorded as having come from the same URL we are
# about to ask for. Its script saying it would download that URL *today* is not evidence
# about the file on its disk: a worktree that fetched its dependencies while on
# Version6.4 (which points several of these at a different build) and has since switched
# branches would pass that test while holding the wrong binaries -- and because we borrow
# the newest copy, timestamp and all, that wrong file would win the conditional GET below
# and be locked in.
if [ "$(recorded_source "$tree/${sources_file#../}" "$2")" != "$1" ]
then
continue
fi
# Never spread around an error page, or a zip that is not a zip: junk left by an older
# version of this script would otherwise propagate from worktree to worktree, and a
# damaged zip would defeat extract_zip's delete-and-refetch recovery by being re-borrowed
# every run.
if looks_like_html "$candidate"
then
continue
fi
case "$candidate" in
*.zip)
if ! unzip -tqq "$candidate" > /dev/null 2>&1
then
continue
fi
;;
esac
if [ -z "$newest" ] || [ "$candidate" -nt "$newest" ]
then
newest="$candidate"
fi
done
if [ -n "$newest" ]
then
echo "copy: $2 <= $newest (already downloaded by another worktree)"
# -p to keep the timestamp, which is what makes the conditional GET meaningful
if cp -p "$newest" "$2"
then
borrowed_dest+=("$2")
borrowed_from+=("$newest")
# Vouch for the borrowed file for this run only -- enough for the conditional GET below to be
# meaningful -- but do not write it into our own record yet. Recording it here would make an
# unverified borrowed copy look, on every later run, like an ordinary local file we had checked
# ourselves. The record gets written when the server actually confirms it.
seeded_dest="$2"
seeded_source="$1"
else
rm -f "$2"
fi
fi
}

copy_auto() {
if [ "$clean" == "1" ]
then
echo cleaning $2
rm -f ""$2""
else
destinations+=("$2")
if [ "$server_unreachable" == "1" ]
then
skipped_after_giving_up=$((skipped_after_giving_up + 1))
return
fi
seeded_dest=""
seeded_source=""
seed_from_sibling_worktree "$1" "$2"
where_curl=$(type -P curl)
where_wget=$(type -P wget)
if [ "$where_curl" != "" ]
then
copy_curl "$1" "$2"
elif [ "$where_wget" != "" ]
then
copy_wget "$1" "$2"
else
echo "Missing curl or wget"
exit 1
fi
fi
}

# Downloads into a temporary file and only replaces the real one once we are happy with what
# arrived. Writing straight to the destination (as this used to) means an error page or a
# truncated transfer becomes, say, our copy of PodcastUtilities.PortableDevices.dll, and the
# C# build then fails with a wildly misleading message.
copy_curl() {
echo "curl: $2 <= $1"
local temp="$2.getDependencies-download"
rm -f "$temp"
current_temp="$temp"
# --speed-limit/--speed-time so a server that accepts the connection and then trickles or
# stalls eventually gives up instead of hanging init.sh for ever; the allowance is generous
# enough that a genuinely slow connection still finishes.
local args=(-# -L --fail --retry 1 --connect-timeout 20 --speed-limit 1024 --speed-time 120
-o "$temp" -w '%{http_code}')
if [ "$force" != "1" ] && [ -s "$2" ] && ! looks_like_html "$2" \
&& { [ "$(recorded_source "$sources_file" "$2")" == "$1" ] \
	|| { [ "$seeded_dest" == "$2" ] && [ "$seeded_source" == "$1" ]; }; }
then
# We have a file that is a plausible copy of this very artifact, so ask the server for it
# only if it has something newer. All three tests matter: an empty or error-page file must
# not be able to answer "not modified", and neither must one we last fetched from a
# different build's URL (see the note on $sources_file above).
args+=(-z "$2")
fi
local http_code
local status
http_code=$(curl "${args[@]}" "$1")
status=$?
if [ "$status" != "0" ]
then
rm -f "$temp"
current_temp=""
if [ "${http_code:-000}" == "000" ]
then
# nothing came back at all: no connection, or it died before sending a response
no_response_run=$((no_response_run + 1))
if [ "$no_response_run" -ge "$give_up_after" ]
then
server_unreachable=1
fi
else
no_response_run=0
fi
note_failure "$2 <= $1: curl failed (exit code $status, HTTP status ${http_code:-none})"
return
fi
no_response_run=0
if [ "$http_code" == "304" ]
then
# our copy is already up to date; curl sent us no content at all
rm -f "$temp"
current_temp=""
record_source "$2" "$1"
note_verified "$2"
return
fi
if [ ! -s "$temp" ]
then
rm -f "$temp"
current_temp=""
note_failure "$2 <= $1: the server sent nothing (HTTP status $http_code)"
return
fi
if looks_like_html "$temp"
then
rm -f "$temp"
current_temp=""
note_failure "$2 <= $1: the server sent an HTML page (HTTP status $http_code) instead of the file we asked for"
return
fi
if ! mv -f "$temp" "$2"
then
rm -f "$temp"
current_temp=""
note_failure "$2 <= $1: downloaded it, but could not put it in place (is something using the old file?)"
return
fi
current_temp=""
record_source "$2" "$1"
note_verified "$2"
}

# The wget fallback (used only where curl is missing, which on Windows is nowhere we know of)
# has to be just as careful as copy_curl. It is true that wget does not save the body of a 4xx
# or 5xx response, but that is not the case this script exists to survive: an HTML page served
# with a 200 status by a proxy or captive portal is a perfectly ordinary response, and the old
# "wget -N" wrote it straight over the good file. So download to a temporary file and apply the
# same checks. Using -O rules out -N (they are incompatible), meaning this path always fetches
# the whole file rather than asking "only if newer" -- a fair price for a fallback that is
# hardly ever taken, and it is why the basename/%-escaping dance this function used to need is
# gone: -O names the file exactly.
copy_wget() {
echo "wget: $2 <= $1"
local temp="$2.getDependencies-download"
rm -f "$temp"
current_temp="$temp"
if ! wget -q -L -O "$temp" "$1"
then
rm -f "$temp"
current_temp=""
note_failure "$2 <= $1: wget failed"
return
fi
if [ ! -s "$temp" ]
then
rm -f "$temp"
current_temp=""
note_failure "$2 <= $1: the server sent nothing"
return
fi
if looks_like_html "$temp"
then
rm -f "$temp"
current_temp=""
note_failure "$2 <= $1: the server sent an HTML page instead of the file we asked for"
return
fi
if ! mv -f "$temp" "$2"
then
rm -f "$temp"
current_temp=""
note_failure "$2 <= $1: downloaded it, but could not put it in place (is something using the old file?)"
return
fi
current_temp=""
record_source "$2" "$1"
note_verified "$2"
}


