# make sure output directories exist
mkdir -p ../DistFiles
mkdir -p ../DistFiles/ghostscript
mkdir -p ../Downloads
mkdir -p ../build
mkdir -p ../lib
mkdir -p ../lib/dotnet
mkdir -p ../lib/lame

# Sweep up after any previous run that was interrupted. We cannot rely on the trap above for
# this: init.sh starts this script in the background, a non-interactive shell makes its
# background children ignore SIGINT, and bash will not install a trap for a signal that was
# already ignored -- so a Ctrl-C during ./init.sh never reaches us.
rm -f ../DistFiles/*.getDependencies-download ../DistFiles/ghostscript/*.getDependencies-download 	../build/*.getDependencies-download ../Downloads/*.getDependencies-download 	../lib/*.getDependencies-download ../lib/dotnet/*.getDependencies-download 	../lib/lame/*.getDependencies-download 2>/dev/null

# download artifact dependencies
copy_auto https://build.palaso.org/guestAuth/repository/download/bt396/latest.lastSuccessful/ghostscript-win32.zip ../Downloads/ghostscript-win32.zip
copy_auto https://build.palaso.org/guestAuth/repository/download/bt396/latest.lastSuccessful/connections.dll ../DistFiles/connections.dll
copy_auto https://build.palaso.org/guestAuth/repository/download/bt396/latest.lastSuccessful/MSBuild.Community.Tasks.dll ../build/MSBuild.Community.Tasks.dll
copy_auto https://build.palaso.org/guestAuth/repository/download/bt396/latest.lastSuccessful/MSBuild.Community.Tasks.Targets ../build/MSBuild.Community.Tasks.Targets
copy_auto https://build.palaso.org/guestAuth/repository/download/bt396/latest.lastSuccessful/Lame.zip ../Downloads/Lame.zip
copy_auto https://build.palaso.org/guestAuth/repository/download/bt396/latest.lastSuccessful/gm64.zip ../Downloads/gm64.zip
copy_auto https://build.palaso.org/guestAuth/repository/download/bt396/latest.lastSuccessful/meddle.exe ../lib/dotnet/meddle.exe
copy_auto https://build.palaso.org/guestAuth/repository/download/bt396/latest.lastSuccessful/ffmpeg.zip ../Downloads/ffmpeg.zip
