copy_auto https://build.palaso.org/guestAuth/repository/download/Bloom_PortableDevicesFromPodcastUtitlies/latest.lastSuccessful/PodcastUtilities.PortableDevices.pdb ../lib/dotnet/PodcastUtilities.PortableDevices.pdb
copy_auto https://build.palaso.org/guestAuth/repository/download/Bloom_PortableDevicesFromPodcastUtitlies/latest.lastSuccessful/Interop.PortableDeviceApiLib.dll ../lib/dotnet/Interop.PortableDeviceApiLib.dll
copy_auto https://build.palaso.org/guestAuth/repository/download/Bloom_PortableDevicesFromPodcastUtitlies/latest.lastSuccessful/Interop.PortableDeviceTypesLib.dll ../lib/dotnet/Interop.PortableDeviceTypesLib.dll
copy_auto https://build.palaso.org/guestAuth/repository/download/Bloom_Help_BloomHelp65/latest.lastSuccessful/Bloom.chm ../DistFiles/Bloom.chm
copy_auto https://build.palaso.org/guestAuth/repository/download/XliffForHtml_WindowsMasterContinuous/latest.lastSuccessful/HtmlXliff.exe ../lib/dotnet/HtmlXliff.exe
copy_auto https://build.palaso.org/guestAuth/repository/download/XliffForHtml_WindowsMasterContinuous/latest.lastSuccessful/HtmlXliff.pdb ../lib/dotnet/HtmlXliff.pdb
copy_auto https://build.palaso.org/guestAuth/repository/download/XliffForHtml_WindowsMasterContinuous/latest.lastSuccessful/HtmlAgilityPack.dll ../lib/dotnet/HtmlAgilityPack.dll
# Calling unzip directly and ignoring the result (as this used to) leaves the destination
# silently empty or half-populated when a download was damaged or never happened. So check
# the archive first, and throw away a bad one so that the next run downloads it again
# instead of trusting its timestamp.
extract_zip() {
if [ "$clean" == "1" ]
then
return 0
fi
if [ ! -f "$1" ]
then
extraction_failed=1
note_failure "cannot extract $1 into $2: the file is not there"
return
fi
if ! unzip -tqq "$1" > /dev/null 2>&1
then
extraction_failed=1
deleted_a_corrupt_zip=1
if [ -d "$2" ] && [ -n "$(ls -A "$2" 2>/dev/null)" ]
then
note_failure "cannot extract $1 into $2: it is not a valid zip file (a failed or truncated download?). Deleted it so the next run fetches it afresh; what an earlier run extracted into $2 is still there."
else
note_failure "cannot extract $1 into $2: it is not a valid zip file (a failed or truncated download?). Deleted it so the next run fetches it afresh, and nothing has been extracted into $2."
fi
rm -f "$1"
return
fi
unzip -uqo "$1" -d "$2"
# unzip's exit code 1 means "it worked, with warnings" (a filename it had to adjust, say), so
# only 2 and up are real failures. Treating 1 as a failure would fail the whole of init.sh
# over a cosmetic complaint.
local status=$?
if [ "$status" -ge 2 ]
then
extraction_failed=1
note_failure "failed to extract $1 into $2 (unzip exit code $status)"
fi
}

if [ "$server_unreachable" == "1" ]
then
note_failure "gave up asking build.palaso.org after $give_up_after dependencies in a row got no response at all; skipped the remaining $skipped_after_giving_up download(s)"
fi

# extract downloaded zip files
extract_zip ../Downloads/ghostscript-win32.zip "../DistFiles/ghostscript"
extract_zip ../Downloads/Lame.zip "../lib/lame"
extract_zip ../Downloads/gm64.zip "../lib"
extract_zip ../Downloads/ffmpeg.zip "../lib"

# exit non-zero (with a summary) if anything above failed
report_failures
# End of script
